<template><view class="page"><view class="brand-wrap"><SuilinLogo size="lg"/><text class="brand">岁邻</text><text class="title">创建账号</text><text class="sub">从今天起，把牵挂放得更近一点</text></view><view class="card"><text class="label">手机号</text><input v-model="form.phone" class="input" type="number" maxlength="11" placeholder="请输入手机号"/><text class="label">姓名</text><input v-model="form.name" class="input" maxlength="20" placeholder="请输入姓名"/><text class="label">密码</text><input v-model="form.password" class="input" type="password" placeholder="至少6位"/><text class="label">确认密码</text><input v-model="form.confirmPassword" class="input" type="password" placeholder="再次输入密码"/><text class="label">使用身份</text><view class="roles"><view class="role" :class="{active:form.role==='elder'}" @tap="form.role='elder'">长辈</view><view class="role" :class="{active:form.role==='family'}" @tap="form.role='family'">家属</view></view><button class="primary" @tap="submit">注册</button><view class="links"><text @tap="goLogin">已有账号，去登录</text><text @tap="goBack">返回首页</text></view></view></view></template><script>import SuilinLogo from '@/components/SuilinLogo.vue';export default{components:{SuilinLogo},data(){return{form:{phone:'',name:'',password:'',confirmPassword:'',role:'family'}}},methods:{submit(){const f=this.form;if(!/^1\d{10}$/.test(f.phone))return uni.showToast({title:'请输入正确手机号',icon:'none'});if(!f.name.trim())return uni.showToast({title:'请输入姓名',icon:'none'});if(f.password.length<6)return uni.showToast({title:'密码至少6位',icon:'none'});if(f.password!==f.confirmPassword)return uni.showToast({title:'两次密码不一致',icon:'none'});uni.setStorageSync('suilin_demo_user',{phone:f.phone,name:f.name,role:f.role});uni.showToast({title:'注册成功',icon:'success'});setTimeout(()=>uni.reLaunch({url:f.role==='elder'?'/pages/elder/index':'/pages/family/home/index'}),500)},goLogin(){uni.navigateTo({url:'/pages/login/index'})},goBack(){uni.navigateBack({fail:()=>uni.reLaunch({url:'/pages/entry/index'})})}}}</script><style scoped>.page{min-height:100vh;padding:90rpx 36rpx 60rpx;background:radial-gradient(circle at 90% 6%,rgba(255,206,153,.3),transparent 26%),linear-gradient(180deg,#fff7ee,#fffdf9);box-sizing:border-box}.brand-wrap{text-align:center}.brand-wrap :deep(.suilin-logo){margin:0 auto 10rpx}.brand{display:block;font-size:52rpx;font-weight:900;letter-spacing:8rpx;color:#4b3b33}.title{display:block;margin-top:14rpx;font-size:40rpx;font-weight:900;color:#4b3b33}.sub{display:block;margin-top:10rpx;color:#9a8172;font-size:23rpx}.card{margin-top:30rpx;padding:30rpx;background:rgba(255,255,255,.95);border:1rpx solid #f6e5d6;border-radius:32rpx;box-shadow:0 18rpx 50rpx rgba(116,75,47,.07)}.label{display:block;margin:20rpx 0 10rpx;font-size:22rpx;color:#7e675a}.input{height:82rpx;padding:0 20rpx;background:#fff8f2;border-radius:18rpx}.roles{display:flex;gap:16rpx}.role{flex:1;padding:22rpx;text-align:center;background:#f8f5f1;border-radius:18rpx;color:#817167}.role.active{background:#e7f5f1;color:#2d8e80;font-weight:800}.primary{margin-top:30rpx;background:linear-gradient(135deg,#f0a054,#e9893d);color:#fff;border-radius:20rpx}.links{display:flex;justify-content:space-between;margin-top:22rpx;font-size:22rpx;color:#82695b}</style>